-- SchoolLedger schema v1. PostgreSQL 15+ — all money is integer minor units.
CREATE TABLE schools (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(190) NOT NULL, address TEXT, phone VARCHAR(60), email VARCHAR(190), website VARCHAR(190), logo_path VARCHAR(190), currency CHAR(3) NOT NULL DEFAULT 'TZS', timezone VARCHAR(80) NOT NULL DEFAULT 'Africa/Dar_es_Salaam', invoice_prefix VARCHAR(12) NOT NULL DEFAULT 'INV', receipt_prefix VARCHAR(12) NOT NULL DEFAULT 'RCT', active SMALLINT NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE permissions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR(80) NOT NULL UNIQUE);
CREATE TABLE roles (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, school_id BIGINT NOT NULL, name VARCHAR(100) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (school_id,id), FOREIGN KEY (school_id) REFERENCES schools(id), UNIQUE (school_id,name));
CREATE TABLE role_permissions (role_id BIGINT NOT NULL, permission_id BIGINT NOT NULL, PRIMARY KEY (role_id,permission_id), FOREIGN KEY (role_id) REFERENCES roles(id), FOREIGN KEY (permission_id) REFERENCES permissions(id));
CREATE TABLE academic_years (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, school_id BIGINT NOT NULL, name VARCHAR(100) NOT NULL, starts_on DATE NOT NULL, ends_on DATE NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (school_id,id), FOREIGN KEY (school_id) REFERENCES schools(id), UNIQUE (school_id,name), CHECK (ends_on>=starts_on));
CREATE TABLE terms (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, school_id BIGINT NOT NULL, academic_year_id BIGINT NOT NULL, name VARCHAR(100) NOT NULL, starts_on DATE NOT NULL, ends_on DATE NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (school_id,id), FOREIGN KEY (school_id) REFERENCES schools(id), FOREIGN KEY (school_id,academic_year_id) REFERENCES academic_years(school_id,id), UNIQUE (school_id,academic_year_id,name), CHECK (ends_on>=starts_on));
CREATE TABLE classes (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, school_id BIGINT NOT NULL, name VARCHAR(100) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (school_id,id), FOREIGN KEY (school_id) REFERENCES schools(id), UNIQUE (school_id,name));
CREATE TABLE streams (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, school_id BIGINT NOT NULL, class_id BIGINT NOT NULL, name VARCHAR(100) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (school_id,id), FOREIGN KEY (school_id) REFERENCES schools(id), FOREIGN KEY (school_id,class_id) REFERENCES classes(school_id,id), UNIQUE (school_id,class_id,name));
CREATE TABLE student_types (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, school_id BIGINT NOT NULL, name VARCHAR(100) NOT NULL, requires_boarding SMALLINT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (school_id,id), FOREIGN KEY (school_id) REFERENCES schools(id), UNIQUE (school_id,name));
CREATE TABLE students (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, school_id BIGINT NOT NULL, admission_number VARCHAR(80) NOT NULL, first_name VARCHAR(100) NOT NULL, middle_name VARCHAR(100), last_name VARCHAR(100) NOT NULL, gender VARCHAR(30) NOT NULL, date_of_birth DATE NOT NULL, admission_date DATE NOT NULL, phone VARCHAR(60), email VARCHAR(190), guardian_name VARCHAR(190), guardian_phone VARCHAR(60), address TEXT, photo_path VARCHAR(190), status VARCHAR(30) NOT NULL DEFAULT 'Active', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (school_id,id), FOREIGN KEY (school_id) REFERENCES schools(id), UNIQUE (school_id,admission_number), CHECK (status IN ('Active','Graduated','Transferred','Withdrawn','Suspended')));
CREATE TABLE student_academic_history (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, school_id BIGINT NOT NULL, student_id BIGINT NOT NULL, academic_year_id BIGINT NOT NULL, class_id BIGINT NOT NULL, stream_id BIGINT NULL, student_type_id BIGINT NOT NULL, starts_on DATE NOT NULL, is_current SMALLINT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (school_id,id), FOREIGN KEY (school_id) REFERENCES schools(id), FOREIGN KEY (school_id,student_id) REFERENCES students(school_id,id), FOREIGN KEY (school_id,academic_year_id) REFERENCES academic_years(school_id,id), FOREIGN KEY (school_id,class_id) REFERENCES classes(school_id,id), FOREIGN KEY (school_id,stream_id) REFERENCES streams(school_id,id), FOREIGN KEY (school_id,student_type_id) REFERENCES student_types(school_id,id), UNIQUE (school_id,student_id,is_current), CHECK (is_current IS NULL OR is_current=1));
CREATE TABLE users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, school_id BIGINT NULL, role_id BIGINT NULL, student_id BIGINT NULL, name VARCHAR(190) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, is_super SMALLINT NOT NULL DEFAULT 0, active SMALLINT NOT NULL DEFAULT 1, session_version INT NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (school_id,id), FOREIGN KEY (school_id) REFERENCES schools(id), FOREIGN KEY (school_id,role_id) REFERENCES roles(school_id,id), FOREIGN KEY (school_id,student_id) REFERENCES students(school_id,id), CHECK ((is_super=1 AND school_id IS NULL AND role_id IS NULL) OR (is_super=0 AND school_id IS NOT NULL AND role_id IS NOT NULL)));
CREATE TABLE hostels (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, school_id BIGINT NOT NULL, name VARCHAR(100) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (school_id,id), FOREIGN KEY (school_id) REFERENCES schools(id), UNIQUE (school_id,name));
CREATE TABLE rooms (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, school_id BIGINT NOT NULL, hostel_id BIGINT NOT NULL, name VARCHAR(100) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (school_id,id), FOREIGN KEY (school_id) REFERENCES schools(id), FOREIGN KEY (school_id,hostel_id) REFERENCES hostels(school_id,id), UNIQUE (school_id,hostel_id,name));
CREATE TABLE beds (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, school_id BIGINT NOT NULL, room_id BIGINT NOT NULL, name VARCHAR(100) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (school_id,id), FOREIGN KEY (school_id) REFERENCES schools(id), FOREIGN KEY (school_id,room_id) REFERENCES rooms(school_id,id), UNIQUE (school_id,room_id,name));
CREATE TABLE boarding_assignments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, school_id BIGINT NOT NULL, student_id BIGINT NOT NULL, bed_id BIGINT NOT NULL, meals VARCHAR(190), starts_on DATE NOT NULL, ends_on DATE NULL, is_current SMALLINT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (school_id,id), FOREIGN KEY (school_id) REFERENCES schools(id), FOREIGN KEY (school_id,student_id) REFERENCES students(school_id,id), FOREIGN KEY (school_id,bed_id) REFERENCES beds(school_id,id), UNIQUE (school_id,bed_id,is_current), UNIQUE (school_id,student_id,is_current), CHECK (is_current IS NULL OR is_current=1));
CREATE TABLE fee_types (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, school_id BIGINT NOT NULL, name VARCHAR(100) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (school_id,id), FOREIGN KEY (school_id) REFERENCES schools(id), UNIQUE (school_id,name));
CREATE TABLE fee_structures (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, school_id BIGINT NOT NULL, academic_year_id BIGINT NOT NULL, term_id BIGINT NOT NULL, class_id BIGINT NOT NULL, student_type_id BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (school_id,id), FOREIGN KEY (school_id) REFERENCES schools(id), FOREIGN KEY (school_id,academic_year_id) REFERENCES academic_years(school_id,id), FOREIGN KEY (school_id,term_id) REFERENCES terms(school_id,id), FOREIGN KEY (school_id,class_id) REFERENCES classes(school_id,id), FOREIGN KEY (school_id,student_type_id) REFERENCES student_types(school_id,id), UNIQUE (school_id,academic_year_id,term_id,class_id,student_type_id));
CREATE TABLE fee_structure_items (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, school_id BIGINT NOT NULL, fee_structure_id BIGINT NOT NULL, fee_type_id BIGINT NOT NULL, amount BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (school_id,id), FOREIGN KEY (school_id) REFERENCES schools(id), FOREIGN KEY (school_id,fee_structure_id) REFERENCES fee_structures(school_id,id), FOREIGN KEY (school_id,fee_type_id) REFERENCES fee_types(school_id,id), UNIQUE (school_id,fee_structure_id,fee_type_id), CHECK (amount>0));
CREATE TABLE invoices (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, school_id BIGINT NOT NULL, student_id BIGINT NOT NULL, enrollment_id BIGINT NOT NULL, term_id BIGINT NOT NULL, number VARCHAR(80) NULL, issued_on DATE NOT NULL, due_on DATE NOT NULL, cancelled_at TIMESTAMP NULL, cancellation_reason TEXT, created_by BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (school_id,id), FOREIGN KEY (school_id) REFERENCES schools(id), FOREIGN KEY (school_id,student_id) REFERENCES students(school_id,id), FOREIGN KEY (school_id,enrollment_id) REFERENCES student_academic_history(school_id,id), FOREIGN KEY (school_id,term_id) REFERENCES terms(school_id,id), FOREIGN KEY (created_by) REFERENCES users(id), UNIQUE (school_id,number), UNIQUE (school_id,student_id,term_id), CHECK (due_on>=issued_on));
CREATE TABLE invoice_items (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, school_id BIGINT NOT NULL, invoice_id BIGINT NOT NULL, fee_type_id BIGINT NOT NULL, description VARCHAR(190) NOT NULL, amount BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (school_id,id), FOREIGN KEY (school_id) REFERENCES schools(id), FOREIGN KEY (school_id,invoice_id) REFERENCES invoices(school_id,id), FOREIGN KEY (school_id,fee_type_id) REFERENCES fee_types(school_id,id), CHECK (amount>0));
CREATE TABLE adjustments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, school_id BIGINT NOT NULL, invoice_id BIGINT NOT NULL, kind VARCHAR(30) NOT NULL, amount BIGINT NOT NULL, reason VARCHAR(500) NOT NULL, posted_on DATE NOT NULL, created_by BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (school_id,id), FOREIGN KEY (school_id) REFERENCES schools(id), FOREIGN KEY (school_id,invoice_id) REFERENCES invoices(school_id,id), FOREIGN KEY (created_by) REFERENCES users(id), CHECK (amount<>0), CHECK (kind IN ('Additional charge','Discount','Penalty','Adjustment','Credit')));
CREATE TABLE payments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, school_id BIGINT NOT NULL, student_id BIGINT NOT NULL, amount BIGINT NOT NULL, paid_on DATE NOT NULL, method VARCHAR(30) NOT NULL, reference VARCHAR(190) NULL, notes VARCHAR(500), received_by BIGINT NOT NULL, request_key VARCHAR(64) NOT NULL, reversed_at TIMESTAMP NULL, reversal_reason VARCHAR(500) NULL, reversed_by BIGINT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (school_id,id), FOREIGN KEY (school_id) REFERENCES schools(id), FOREIGN KEY (school_id,student_id) REFERENCES students(school_id,id), FOREIGN KEY (received_by) REFERENCES users(id), FOREIGN KEY (reversed_by) REFERENCES users(id), UNIQUE (school_id,request_key), UNIQUE (school_id,method,reference), CHECK (amount>0), CHECK (method IN ('Cash','Bank','Mobile Money','Cheque','Other')));
CREATE TABLE payment_allocations (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, school_id BIGINT NOT NULL, payment_id BIGINT NOT NULL, invoice_id BIGINT NOT NULL, amount BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (school_id,id), FOREIGN KEY (school_id) REFERENCES schools(id), FOREIGN KEY (school_id,payment_id) REFERENCES payments(school_id,id), FOREIGN KEY (school_id,invoice_id) REFERENCES invoices(school_id,id), UNIQUE (school_id,payment_id,invoice_id), CHECK (amount>0));
CREATE TABLE receipts (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, school_id BIGINT NOT NULL, payment_id BIGINT NOT NULL, number VARCHAR(80) NULL, balance_after BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (school_id,id), FOREIGN KEY (school_id) REFERENCES schools(id), FOREIGN KEY (school_id,payment_id) REFERENCES payments(school_id,id), UNIQUE (school_id,payment_id), UNIQUE (school_id,number));
CREATE TABLE audit_logs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, school_id BIGINT NULL, user_id BIGINT NULL, action VARCHAR(100) NOT NULL, entity VARCHAR(100) NOT NULL, record_id BIGINT NOT NULL, description TEXT, ip_address VARCHAR(45), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (school_id) REFERENCES schools(id), FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE login_attempts (attempt_key CHAR(64) PRIMARY KEY, failures INT NOT NULL DEFAULT 0, started_at TIMESTAMP NOT NULL);
CREATE TABLE school_settings (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, school_id BIGINT NOT NULL, setting_key VARCHAR(100) NOT NULL, setting_value TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (school_id,id), FOREIGN KEY (school_id) REFERENCES schools(id), UNIQUE (school_id,setting_key));
CREATE TABLE subscriptions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, school_id BIGINT NOT NULL, plan VARCHAR(80) NOT NULL DEFAULT 'Basic', status VARCHAR(30) NOT NULL DEFAULT 'trial', expires_on DATE NULL, feature_limits JSON NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (school_id,id), FOREIGN KEY (school_id) REFERENCES schools(id), UNIQUE (school_id));
CREATE TABLE notification_outbox (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, school_id BIGINT NOT NULL, event_type VARCHAR(100) NOT NULL, payload JSON NOT NULL, delivered_at TIMESTAMP NULL, attempts INT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (school_id,id), FOREIGN KEY (school_id) REFERENCES schools(id));
CREATE VIEW invoice_balances AS SELECT i.*, COALESCE(ch.total,0)+COALESCE(ad.total,0) total, COALESCE(pa.total,0) paid, COALESCE(ch.total,0)+COALESCE(ad.total,0)-COALESCE(pa.total,0) balance FROM invoices i LEFT JOIN (SELECT school_id,invoice_id,SUM(amount) total FROM invoice_items GROUP BY school_id,invoice_id) ch ON ch.school_id=i.school_id AND ch.invoice_id=i.id LEFT JOIN (SELECT school_id,invoice_id,SUM(amount) total FROM adjustments GROUP BY school_id,invoice_id) ad ON ad.school_id=i.school_id AND ad.invoice_id=i.id LEFT JOIN (SELECT a.school_id,a.invoice_id,SUM(a.amount) total FROM payment_allocations a JOIN payments p ON p.school_id=a.school_id AND p.id=a.payment_id WHERE p.reversed_at IS NULL GROUP BY a.school_id,a.invoice_id) pa ON pa.school_id=i.school_id AND pa.invoice_id=i.id;
CREATE TABLE platform_settings (setting_key VARCHAR(100) PRIMARY KEY, setting_value TEXT);

CREATE INDEX students_lookup_1 ON students (school_id,last_name,first_name);
CREATE INDEX students_lookup_2 ON students (school_id,phone);
CREATE INDEX invoices_lookup_1 ON invoices (school_id,due_on);
CREATE INDEX payments_lookup_1 ON payments (school_id,paid_on);
CREATE INDEX audit_logs_lookup_1 ON audit_logs (school_id,created_at);
CREATE INDEX notification_outbox_lookup_1 ON notification_outbox (school_id,delivered_at);
CREATE TABLE stored_images (school_id BIGINT NOT NULL REFERENCES schools(id), name CHAR(44) NOT NULL, contents BYTEA NOT NULL, PRIMARY KEY (school_id,name));
